// Define our 5 angles
const angles = [
  "Architectural Breakdown", 
  "Bottleneck & Cost of Inaction", 
  "Contrarian / Unpopular Take", 
  "Client Transformation Story", 
  "Quick Strategic Tip"
];

// Pick one at random
const randomAngle = angles[Math.floor(Math.random() * angles.length)];

// Pass the Airtable data and the new Angle to the AI
return {
  json: {
    Topic: $input.item.json.fields["Topic/system name"],
    Pillar: $input.item.json.fields.Pillar,
    Context: $input.item.json.fields["Core Context & Metrics"],
    Takeaway: $input.item.json.fields["Key Takeaway/Lesson"],
    Selected_Angle: randomAngle
  }
};

// 1. Clean the AI markdown formatting before parsing the JSON
let rawText = $input.item.json.text || "{}";
rawText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
const aiData = JSON.parse(rawText);

// 2. Extract Data
const visualType = aiData.visual_type || "flowchart";
const badgeText = (aiData.badge_text || "SYSTEMS INTEGRATION").toUpperCase();
const clientText = aiData.client_text || "Client: Internal";
const title = aiData.title || "The Infrastructure Pipeline";
const n1 = aiData.node_1 || "Initial State";
const n2 = aiData.node_2 || "Processing";
const n3 = aiData.node_3 || "Output / Result";

// 3. Base Brand CSS (Slate, Glows, Glassmorphism)
const baseCSS = `
  * { box-sizing: border-box; margin: 0; padding: 0; font-family: 'Inter', sans-serif; }
  body {
    width: 1080px; height: 1080px;
    background-color: #121214;
    background-image:
      radial-gradient(circle at 15% 50%, rgba(16, 185, 129, 0.08) 0%, transparent 50%),
      radial-gradient(circle at 85% 30%, rgba(56, 189, 248, 0.08) 0%, transparent 50%),
      radial-gradient(rgba(255,255,255,0.05) 1px, transparent 1px);
    background-size: 100% 100%, 100% 100%, 24px 24px;
    display: flex; justify-content: center; align-items: center;
    color: #ffffff; position: relative; overflow: hidden;
  }
  .canvas-border {
    position: absolute; top: 20px; left: 20px; right: 20px; bottom: 20px;
    border: 1px solid rgba(255,255,255,0.06); border-radius: 40px;
    pointer-events: none; z-index: 2;
  }
  .bg-telemetry {
    position: absolute; top: 40px; left: 40px; right: 40px;
    font-family: monospace; font-size: 20px; line-height: 2;
    color: #a1a1aa; opacity: 0.15; white-space: pre; z-index: 1;
    mask-image: linear-gradient(to bottom, rgba(0,0,0,1) 0%, rgba(0,0,0,0) 80%);
    -webkit-mask-image: linear-gradient(to bottom, rgba(0,0,0,1) 0%, rgba(0,0,0,0) 80%);
  }
  .ambient-glow {
    position: absolute; width: 700px; height: 700px;
    background: rgba(16, 185, 129, 0.15);
    filter: blur(120px); z-index: 3; top: 50%; left: 50%; transform: translate(-50%, -50%);
  }
  .helio-card {
    width: 920px; height: 920px;
    background: linear-gradient(145deg, rgba(24, 24, 27, 0.95), rgba(9, 9, 11, 0.98));
    backdrop-filter: blur(20px);
    border-top: 1px solid rgba(255, 255, 255, 0.12);
    border-left: 1px solid rgba(255, 255, 255, 0.08);
    border-right: 1px solid rgba(0, 0, 0, 0.6);
    border-bottom: 1px solid rgba(0, 0, 0, 0.8);
    border-radius: 24px; padding: 70px;
    display: flex; flex-direction: column; position: relative; z-index: 10;
    box-shadow: 0 40px 100px -10px rgba(0, 0, 0, 0.9), inset 0 1px 0 rgba(255,255,255,0.05);
  }
  .header-row { display: flex; gap: 16px; margin-bottom: 50px; align-items: center; }
  .pill {
    background: rgba(16, 185, 129, 0.1); border: 1px solid rgba(16, 185, 129, 0.3);
    border-radius: 99px; padding: 10px 20px;
    font-size: 15px; font-weight: 700; color: #10b981; text-transform: uppercase; letter-spacing: 1.5px;
    box-shadow: 0 0 20px rgba(16, 185, 129, 0.15);
  }
  .client-text { font-size: 18px; font-weight: 500; color: #a1a1aa; letter-spacing: 0.5px; }
  .main-title { font-size: 58px; font-weight: 800; line-height: 1.15; margin-bottom: 60px; letter-spacing: -1px; text-shadow: 0 10px 30px rgba(0,0,0,0.5); }
  .footer { 
    position: absolute; bottom: 60px; left: 70px; right: 70px;
    display: flex; justify-content: space-between; align-items: center;
    border-top: 1px solid rgba(255,255,255,0.1); padding-top: 30px;
  }
  .footer-text { font-size: 16px; font-weight: 700; color: #71717a; letter-spacing: 2px; text-transform: uppercase; }
  .footer-brand { font-size: 20px; font-weight: 800; color: #f4f4f5; display: flex; align-items: center; gap: 10px; }
  .footer-dot { width: 12px; height: 12px; background: #10b981; border-radius: 50%; box-shadow: 0 0 12px #10b981; }
`;

// 4. Dynamic Template Logic
let templateCSS = "";
let contentHTML = "";

if (visualType === "metric_dashboard") {
  // --- METRIC DASHBOARD TEMPLATE ---
  templateCSS = `
    .metric-container { display: flex; flex-direction: column; align-items: center; justify-content: center; flex: 1; margin-bottom: 80px; }
    .metric-value { font-size: 140px; font-weight: 900; color: #10b981; line-height: 1; text-shadow: 0 20px 60px rgba(16, 185, 129, 0.3); letter-spacing: -4px; margin-bottom: 20px; }
    .metric-label { font-size: 32px; font-weight: 600; color: #ffffff; text-align: center; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 20px; }
    .metric-sub { font-size: 22px; color: #a1a1aa; text-align: center; max-width: 80%; font-family: monospace; }
  `;
  contentHTML = `
    <div class="metric-container">
      <div class="metric-value">${n1}</div>
      <div class="metric-label">${n2}</div>
      <div class="metric-sub">> ${n3}</div>
    </div>
  `;
} 
else if (visualType === "split_compare") {
  // --- SPLIT COMPARE TEMPLATE ---
  templateCSS = `
    .split-container { display: flex; gap: 30px; flex: 1; margin-bottom: 80px; }
    .split-card { flex: 1; padding: 40px; border-radius: 16px; display: flex; flex-direction: column; justify-content: center; position: relative; overflow: hidden; }
    .old-way { background: linear-gradient(180deg, rgba(239, 68, 68, 0.05), rgba(0,0,0,0.5)); border: 1px solid rgba(239, 68, 68, 0.2); }
    .new-way { background: linear-gradient(180deg, rgba(16, 185, 129, 0.1), rgba(0,0,0,0.5)); border: 1px solid rgba(16, 185, 129, 0.4); box-shadow: 0 10px 40px rgba(16,185,129,0.1); transform: scale(1.02); }
    .split-label { font-family: monospace; font-size: 16px; letter-spacing: 2px; margin-bottom: 20px; }
    .old-way .split-label { color: #ef4444; }
    .new-way .split-label { color: #10b981; }
    .split-text { font-size: 26px; font-weight: 500; line-height: 1.6; color: #f4f4f5; }
    .old-way .split-text { color: #a1a1aa; text-decoration: line-through; opacity: 0.7; }
  `;
  contentHTML = `
    <div class="split-container">
      <div class="split-card old-way">
        <div class="split-label">[ LEGACY METHOD ]</div>
        <div class="split-text">${n1}</div>
      </div>
      <div class="split-card new-way">
        <div class="split-label">[ HELIOCONVERT ARCHITECTURE ]</div>
        <div class="split-text">${n2}</div>
      </div>
    </div>
  `;
}
else if (visualType === "tech_stack") {
  // --- TECH STACK TEMPLATE ---
  templateCSS = `
    .stack-container { display: flex; flex-direction: column; gap: 40px; flex: 1; margin-bottom: 80px; position: relative; }
    .stack-line { position: absolute; left: 50%; top: 40px; bottom: 40px; width: 2px; background: linear-gradient(to bottom, rgba(16,185,129,0) 0%, rgba(16,185,129,0.5) 50%, rgba(16,185,129,0) 100%); transform: translateX(-50%); z-index: 0; }
    .stack-item { background: rgba(24, 24, 27, 0.8); border: 1px solid rgba(255,255,255,0.1); padding: 25px 40px; border-radius: 12px; display: flex; justify-content: center; align-items: center; z-index: 1; margin: 0 auto; min-width: 60%; text-align: center; box-shadow: 0 10px 30px rgba(0,0,0,0.5); backdrop-filter: blur(10px); }
    .stack-item:nth-child(2) { border-color: #38bdf8; box-shadow: 0 10px 30px rgba(56, 189, 248, 0.15); }
    .stack-item:nth-child(3) { border-color: #10b981; box-shadow: 0 10px 30px rgba(16, 185, 129, 0.15); transform: scale(1.05); }
    .stack-text { font-size: 28px; font-weight: 700; color: #f4f4f5; font-family: monospace; letter-spacing: 1px; }
  `;
  contentHTML = `
    <div class="stack-container">
      <div class="stack-line"></div>
      <div class="stack-item"><div class="stack-text">${n1}</div></div>
      <div class="stack-item"><div class="stack-text">${n2}</div></div>
      <div class="stack-item"><div class="stack-text">${n3}</div></div>
    </div>
  `;
}
else {
  // --- DEFAULT FLOWCHART TEMPLATE ---
  templateCSS = `
    .flow-container { display: flex; flex-direction: column; gap: 20px; position: relative; margin-left: 10px; flex: 1; margin-bottom: 80px; }
    .flow-line { position: absolute; left: 34px; top: 40px; bottom: 40px; width: 2px; background: linear-gradient(to bottom, rgba(255,255,255,0.05) 0%, rgba(16,185,129,0.5) 50%, rgba(255,255,255,0.05) 100%); z-index: 0; }
    .flow-step { display: flex; align-items: center; gap: 30px; z-index: 1; background: rgba(0,0,0,0.3); padding: 20px 30px; border-radius: 16px; border: 1px solid rgba(255,255,255,0.05); }
    .flow-step.active { background: linear-gradient(90deg, rgba(16, 185, 129, 0.1), rgba(0,0,0,0.3)); border: 1px solid rgba(16, 185, 129, 0.4); box-shadow: 0 10px 30px rgba(0,0,0,0.5); transform: scale(1.02); }
    .step-num { width: 70px; height: 70px; border-radius: 50%; background: #09090b; border: 2px solid #3f3f46; display: flex; justify-content: center; align-items: center; font-family: monospace; font-size: 26px; color: #a1a1aa; font-weight: bold; box-shadow: 0 4px 10px rgba(0,0,0,0.5); z-index: 2; }
    .active .step-num { border-color: #10b981; color: #10b981; background: rgba(16, 185, 129, 0.1); box-shadow: 0 0 20px rgba(16, 185, 129, 0.4); }
    .step-text { font-size: 32px; font-weight: 500; color: #a1a1aa; }
    .active .step-text { color: #ffffff; font-weight: 700; }
  `;
  contentHTML = `
    <div class="flow-container">
      <div class="flow-line"></div>
      <div class="flow-step">
        <div class="step-num">1</div><div class="step-text">${n1}</div>
      </div>
      <div class="flow-step active">
        <div class="step-num">2</div><div class="step-text">${n2}</div>
      </div>
      <div class="flow-step">
        <div class="step-num">3</div><div class="step-text">${n3}</div>
      </div>
    </div>
  `;
}

// 5. Assemble Final HTML
const htmlPayload = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
  <style>
    ${baseCSS}
    ${templateCSS}
  </style>
</head>
<body>
  <div class="canvas-border"></div>
  <div class="bg-telemetry">&gt; [SYS] Initializing runtime environment...
&gt; [SYS] Routing payload to HelioConvert engine...
&gt; [DB] Connection pool active (postgres://heliodb)
&gt; [API] 200 OK - Response Time: 42ms
&gt; [SEC] Infrastructure handshake verified
&gt; [REV] Pipeline health score: 99.8%</div>
  <div class="ambient-glow"></div>
  <div class="helio-card">
    <div class="header-row">
      <div class="pill">${badgeText}</div>
      <div class="client-text">${clientText}</div>
    </div>
    <div class="main-title">${title}</div>

    ${contentHTML}

    <div class="footer">
      <div class="footer-text">VIEW ARCHITECTURE ⌄</div>
      <div class="footer-brand"><div class="footer-dot"></div> HelioConvert</div>
    </div>
  </div>
</body>
</html>
`;

return { json: { html: htmlPayload } };
